"""Generate ``requirements.lock`` for the host MCP adapter runtime (T-2915).

The lock is produced WITHOUT installing anything: pip resolves the
``requirements.in`` pins for the fixed target platform in ``--dry-run``
mode and writes a JSON installation report; each resolved distribution's
wheel URL and sha256 come straight from that report (pip takes them from
the package index). Wheels only — an sdist would need a build toolchain
on the install host and could not be verified by hash alone.

Usage (developer/HO tool, network required):

    python3 tools/host_mcp_adapter/dist/lock.py            # rewrite lock
    python3 tools/host_mcp_adapter/dist/lock.py --check    # exit 1 if stale

The lock is platform-specific: CPython 3.12 (the founding host's system
interpreter), manylinux x86_64. A different interpreter minor or
architecture needs a regenerated lock; ``--self-check`` reports the
mismatch at runtime.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import subprocess
import sys
import tempfile
from pathlib import Path

DIST_DIR = Path(__file__).resolve().parent
REQUIREMENTS_IN = DIST_DIR / "requirements.in"
REQUIREMENTS_LOCK = DIST_DIR / "requirements.lock"

PYTHON_VERSION = "3.12"
IMPLEMENTATION = "cp"
ABI = "cp312"
PLATFORMS = (
    "manylinux2014_x86_64",
    "manylinux_2_17_x86_64",
    "manylinux_2_28_x86_64",
    "manylinux_2_34_x86_64",
    "manylinux_2_39_x86_64",
)


def requirements_in_sha256() -> str:
    return hashlib.sha256(REQUIREMENTS_IN.read_bytes()).hexdigest()


def resolve(report_path: Path) -> list[dict]:
    command = [
        sys.executable,
        "-m",
        "pip",
        "install",
        "--dry-run",
        "--ignore-installed",
        "--no-cache-dir",
        "--only-binary=:all:",
        "--python-version",
        PYTHON_VERSION,
        "--implementation",
        IMPLEMENTATION,
        "--abi",
        ABI,
    ]
    for platform in PLATFORMS:
        command += ["--platform", platform]
    command += ["--report", str(report_path), "-r", str(REQUIREMENTS_IN), "-q"]
    subprocess.run(command, check=True)
    report = json.loads(report_path.read_text(encoding="utf-8"))
    return list(report["install"])


def render(entries: list[dict]) -> str:
    rows = []
    for entry in entries:
        metadata = entry["metadata"]
        info = entry["download_info"]
        filename = info["url"].rsplit("/", 1)[-1]
        if not filename.endswith(".whl"):
            raise SystemExit(f"refusing non-wheel distribution: {filename}")
        digest = info.get("archive_info", {}).get("hashes", {}).get("sha256")
        if not digest:
            raise SystemExit(f"no sha256 for {filename}")
        rows.append((metadata["name"].lower(), metadata["version"], filename, digest))
    rows.sort()
    lines = [
        "# GENERATED by tools/host_mcp_adapter/dist/lock.py - do not hand-edit.",
        f"# requirements.in sha256: {requirements_in_sha256()}",
        f"# target: CPython {PYTHON_VERSION} ({ABI}), manylinux x86_64; wheels only",
        "# install: pip install --require-hashes --no-deps --only-binary=:all: -r requirements.lock",
    ]
    for name, version, filename, digest in rows:
        lines.append(f"# {filename}")
        lines.append(f"{name}=={version} \\")
        lines.append(f"    --hash=sha256:{digest}")
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    with tempfile.TemporaryDirectory() as tmp:
        text = render(resolve(Path(tmp) / "report.json"))
    if args.check:
        current = REQUIREMENTS_LOCK.read_text(encoding="utf-8")
        if current != text:
            print("requirements.lock is stale", file=sys.stderr)
            return 1
        return 0
    REQUIREMENTS_LOCK.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
